package vn.hust.restaurant.service;import java.sql.*;import java.time.*;import java.util.*;import vn.hust.restaurant.model.Reservation;import vn.hust.restaurant.repository.ReservationRepository;public class ReservationService{private final ReservationRepository r;public ReservationService(ReservationRepository r){this.r=r;}public List<Reservation>upcoming()throws SQLException{return r.upcoming();}public long create(int table,Integer customer,int employee,String name,String phone,LocalDateTime at,int party,String note)throws SQLException{if(at.isBefore(LocalDateTime.now()))throw new IllegalArgumentException("Thời gian đặt phải ở tương lai");return r.create(table,customer,employee,name,phone,at,party,note);}public void cancel(long id)throws SQLException{r.cancel(id);}}
